WITH gaps AS (SELECT *, CASE WHEN started_at - LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at, id) > INTERVAL 7 DAYS THEN 1 ELSE 0 END AS is_new_session FROM sessions), islands AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY customer_id ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM gaps) SELECT s.id, s.customer_id, s.started_at, s.country, s.session_id, (SELECT AVG(x.discount) FROM orders x WHERE x.customer_id = s.customer_id) AS avg_order_discount FROM islands s ORDER BY id;
